import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Chatbot() {
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [options, setOptions] = useState([]);
  const navigate = useNavigate();

  async function sendMessage(message) {
    const userMessage = message || text;
    if (!userMessage.trim()) return;

    // show user message
    setMessages(m => [...m, { from: "user", text: userMessage }]);
    setText("");

    // Backend call
    const res = await fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") + "/api/chat",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userMessage })
      }
    );

    const data = await res.json();

    // Show bot message
    setMessages(m => [...m, { from: "bot", text: data.reply }]);

    // Show options under message
    setOptions(data.options || []);

    // Handle redirect
    if (data.action === "go-events") navigate("/events");
    if (data.action === "go-login") navigate("/login");
    if (data.action === "go-register") navigate("/register");
  }

  return (
    <div className="chatbot">

      <div className="chat-window">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={msg.from === "user" ? "msg user" : "msg bot"}
          >
            {msg.text}
          </div>
        ))}
      </div>

      {/* OPTIONS */}
      <div className="options-row">
        {options.map((opt, i) => (
          <button
            key={i}
            className="option-btn"
            onClick={() => sendMessage(opt)}
          >
            {opt}
          </button>
        ))}
      </div>

      {/* TEXT INPUT */}
      <div className="chat-input">
        <input
          value={text}
          onChange={e => setText(e.target.value)}
          placeholder="Say something..."
        />
        <button onClick={() => sendMessage()}>Send</button>
      </div>
    </div>
  );
}
